function fewestToCancel(bookings: number[][]): number {
  const b = bookings.map(x => [x[0], x[1]]).sort((p, q) => p[1] - q[1]);
  const best = new Array(b.length).fill(1);
  let most = 0;
  for (let i = 0; i < b.length; i++) {
    for (let j = 0; j < i; j++) if (b[j][1] <= b[i][0]) best[i] = Math.max(best[i], best[j] + 1);
    most = Math.max(most, best[i]);
  }
  return b.length - most;
}

