class Solution:
    def fewestToCancel(self, bookings: List[List[int]]) -> int:
        b = sorted(bookings, key=lambda x: x[1])
        best = [1] * len(b)
        for i in range(len(b)):
            for j in range(i):
                if b[j][1] <= b[i][0]:
                    best[i] = max(best[i], best[j] + 1)
        return len(b) - max(best)

