function fewestToCancel(bookings: number[][]): number {
  const b = bookings.map(x => [x[0], x[1]]).sort((p, q) => p[1] - q[1]);
  let lastEnd = -Infinity, cancelled = 0;
  for (const [s, e] of b) {
    if (s >= lastEnd) lastEnd = e;
    else cancelled++;
  }
  return cancelled;
}

